mapper.update:
update chat_credit_session
set refund_state = #{refundState}, update_time = now()
where request_id = #{requestId}

update chat_credit_session
set retry_count = retry_count + 1, update_time = now()
where id = #{id}

mapper.select:
select id, user_id, request_id, deducted, deduct_amount, refund_state, retry_count
from chat_credit_session
where refund_state = 'pending' and retry_count < #{maxRetry}
order by create_time asc
limit #{limit}
